List<int> sortArray(List<int> arr) {
  if (arr.isEmpty || arr.length == 1) return List.from(arr);

  int mid = arr.length ~/ 2;
  final leftHalf = List.from(arr.sublist(0, mid));
  final rightHalf = List.from(arr.sublist(mid));

  // Recursively split and merge the array.
  var sortedLeft = sortArray(leftHalf);
  var sortedRight = sortArray(rightHalf);

  int i = 0; 
  int j = 0;

  while(i < sortedLeft.length && j < sortedRight.length){
    if(sortedLeft[i] <= sortedRight[j]){
      arr.add(sortedLeft.removeAt(i++));   
    }else{
       arr.insertAll(j+sortedLeft.length-sortedRight.length-1,
         [sortedRight.removeAt(j++)]);
     }
   }

if (!sortedLeft.isEmpty)
	arr.addAll(sortedLeft);	

return arr;
}
